bash -c cd /home/CNS2026495165/dsh/.workspace/lag-fix/research-v2/root-subscriptions && python3 - <<'PY'
p='scripts/lib-init-slots.js'
s=open(p,encoding='utf-8').read()
anchor="  const SEL_HOOKS = { 7: 'sections', 10: 'onboardingSteps', 14: 'sessionsInner', 17: 'sessions' };"
assert anchor in s
s=s.replace(anchor, anchor + """

  /** Full 22-slot identity map of the committed SettingsRoot fiber (empirical, no guessing). */
  function fullHookMap(f) {
    const a = f.alternate;
    const out = [];
    let h = f.memoizedState, i = 0;
    while (h && i < 26) {
      const v = h.memoizedState;
      const ha = a ? hookAt(a, i) : null;
      const alt = ha ? ha.memoizedState : '__noalt__';
      out.push({
        i,
        kind: v === null ? 'null' : v === undefined ? 'undefined' : Array.isArray(v) ? 'array' : (v instanceof Set ? 'Set' : typeof v),
        len: Array.isArray(v) ? v.length : (v instanceof Set ? v.size : null),
        val: (typeof v === 'boolean' || typeof v === 'string' || typeof v === 'number') ? v : undefined,
        altPresent: !!ha,
        changed: ha ? v !== alt : null,
        sig: Array.isArray(v) ? JSON.stringify(v).slice(0, 120) : (v && typeof v === 'object' ? Object.keys(v).slice(0, 5).join(',') : String(v)),
      });
      h = h.next; i++;
    }
    return out;
  }""",1)
s=s.replace("""          version: readVersionCounters(f),
          outlet: readAncestorOutlet(f),""","""          version: readVersionCounters(f),
          outlet: readAncestorOutlet(f),
          full: fullHookMap(f),""",1)
open(p,'w',encoding='utf-8').write(s)
print('ok')
PY
node --check scripts/lib-init-slots.js && timeout 200 node scripts/measure.mjs --window 40000 --tag full --states models 2>&1 | tail -4

